export type Response = {
  metadata: Metadata
  /**
   * @description An integer between 0 and 20 specifying the number of most likely tokens to return at each token position, each with an associated log probability. (minimum: 0, maximum: 20)
   */
  top_logprobs?: number | null
  /**
   * @description What sampling temperature to use, between 0 and 2. Higher values like 0.8 will make the output more random, while lower values like 0.2 will make it more focused and deterministic. We generally recommend altering this or top_p but not both. (minimum: 0, maximum: 2, default: 1)
   * @default 1
   */
  temperature: number | null
  /**
   * @description Nucleus sampling: only tokens whose cumulative probability is at most this value are considered. Must be greater than 0; values <= 0 return HTTP 400. Set this or temperature, not both. (minimum: 0, maximum: 1, default: 1)
   * @default 1
   */
  top_p: number | null
  /**
   * @description Deprecated. Being replaced by safety_identifier and prompt_cache_key; use prompt_cache_key to retain caching benefits. A stable end-user identifier used to improve cache hit rates and help detect abuse.
   * @type string | undefined
   */
  user?: string
  /**
   * @description A stable identifier that helps detect users who may be violating usage policies. Use a string that uniquely identifies each user, up to 64 characters; hash a username or email so you do not send identifying information. (maxLength: 64)
   * @maxLength 64
   * @type string | undefined
   */
  safety_identifier?: string
  /**
   * @description Groups similar requests to improve cache hit rates. Replaces the user field.
   * @type string | undefined
   */
  prompt_cache_key?: string
  service_tier?: ServiceTier
  /**
   * @description The retention policy for the prompt cache.
   */
  prompt_cache_retention?: ResponsePromptCacheRetentionKey | null
  /**
   * @description Identifier of a previous response to continue from. Use this to build multi-turn conversations with server-managed state. Cannot be combined with conversation.
   */
  previous_response_id?: string | null
  /**
   * @description ID of the model used to generate the response.
   * @type string
   */
  model: string
  reasoning?: Reasoning | null
  /**
   * @description Whether to run the response asynchronously in the background. Cannot be combined with stream. (default: false)
   * @default false
   */
  background?: boolean | null
  /**
   * @description Maximum number of built-in tool calls allowed while generating a response, counted across all built-in tools rather than per tool. The model ignores any calls beyond this limit. (minimum: 1)
   */
  max_tool_calls?: number | null
  text?: ResponseTextParam
  tools: ToolsArray
  tool_choice: ToolChoiceParamKey
  prompt?: Prompt
  /**
   * @description Truncation strategy for the request. Only disabled (the default) is supported: if the input plus requested output tokens exceed the model's context window, the request fails with a 400 error. The auto strategy is not supported. (default: disabled)
   */
  truncation?: ResponseTruncationKey | null
  /**
   * @description Identifier for this response.
   * @type string
   */
  id: string
  /**
   * @description Object type; always response.
   * @type string
   */
  object: 'response'
  /**
   * @description Generation status: one of completed, failed, in_progress, cancelled, queued, or incomplete.
   * @type string | undefined
   */
  status?: ResponseStatusEnumKey
  /**
   * @description Unix timestamp (seconds) for when the response was created.
   * @type number
   */
  created_at: number
  /**
   * @description Unix timestamp (in seconds) when the response completed. Set only when status is completed.
   */
  completed_at?: number | null
  error: ResponseError
  /**
   * @description Explains why the response is incomplete.
   */
  incomplete_details: object | null
  /**
   * @description The items the model generated. Their number and order depend on the response; where SDKs expose it, prefer the output_text helper over indexing into this array.
   * @type array
   */
  output: OutputItem[]
  /**
   * @description Developer-level instructions inserted at the top of the model's context. When previous_response_id is set, instructions from the prior response are not carried forward, so you can change them on each turn.
   */
  instructions: string | InputItem[] | null
  /**
   * @description SDK-only helper that concatenates the text from all output_text items in output. Available in the Python and JavaScript SDKs.
   */
  output_text?: string | null
  usage?: ResponseUsage
  /**
   * @description Whether the model may run tool calls in parallel. (default: true)
   * @default true
   * @type boolean
   */
  parallel_tool_calls: boolean
  /**
   * @description Whether to persist the generated response so it can be retrieved later and chained from previous_response_id. (default: true)
   * @default true
   */
  store?: boolean | null
  /**
   * @description (default: null)
   */
  conversation?: Conversation2 | null
  /**
   * @description Upper bound on the number of tokens generated for the response, counting both visible output and reasoning tokens.
   */
  max_output_tokens?: number | null
}

